/**
 * Contract review bootstrap — standalone, no fetch / no localhost.
 * Generated by scripts/export_contract_review.py
 */
(function () {
  'use strict';

  function ensureContractHash() {
    var hash = location.hash || '';
    var path = hash.replace(/^#/, '').split('?')[0];
    if (!path || path === '/' || path === '/dashboard') {
      history.replaceState({ path: '/contract/list' }, '', '#/contract/list');
    }
  }

  function initGlobalEvents() {
    document.addEventListener('click', function (e) {
      var toggle = e.target.closest('.dms-menu__toggle');
      if (toggle) {
        toggle.closest('.dms-menu__item').classList.toggle('is-expanded');
      }

      if (e.target.closest('[data-action="sidebar-toggle"]')) {
        document.getElementById('dms-sidebar').classList.toggle('is-collapsed');
      }

      var tab = e.target.closest('.dms-tabs__tab');
      if (tab) {
        var tabs = tab.closest('.dms-tabs');
        tabs.querySelectorAll('.dms-tabs__tab').forEach(function (t) { t.classList.remove('is-active'); });
        tabs.querySelectorAll('.dms-tabs__panel').forEach(function (p) { p.classList.add('is-hidden'); });
        tab.classList.add('is-active');
        var panel = tabs.querySelector('[data-panel="' + tab.dataset.tab + '"]');
        if (panel) panel.classList.remove('is-hidden');
      }

      var collapseHeader = e.target.closest('.dms-collapse__header');
      if (collapseHeader) {
        collapseHeader.closest('.dms-collapse__item').classList.toggle('is-open');
      }
    });
  }

  function initApp() {
    ensureContractHash();

    document.getElementById('app').innerHTML = DMS.render('MainLayout', {
      menuItems: window.__CONTRACT_MENU_ITEMS,
      role: 'Admin',
      userName: 'Vũ BA'
    });

    DMSRouter.register('/contract', window.renderContractList);
    DMSRouter.register('/contract/list', window.renderContractList);
    DMSRouter.register('/dashboard', function () {
      DMSRouter.navigate('/contract/list', true);
      return '';
    });
    DMSRouter.register('*', function () {
      DMSRouter.navigate('/contract/list', true);
      return '';
    });

    DMSRouter.init({ contentEl: document.getElementById('dms-content') });
    initGlobalEvents();
    if (DMS.get('Tooltip') && typeof DMS.get('Tooltip').init === 'function') {
      DMS.get('Tooltip').init();
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initApp);
  } else {
    initApp();
  }
})();
